  str_homeland_dairy_title_1091 = "Estudio de especies",
  str_homeland_dairy_title_1092 = "el mejor genero",
  str_homeland_dairy_title_1093 = "Luz perfecta",
  str_homeland_dairy_title_1094 = "¿Es eso una torre para gatos?",
  str_homeland_dairy_title_1095 = "Holgazán perezoso",
  str_homeland_dairy_title_1096 = "El aliento del agua",
  str_homeland_dairy_title_1097 = "Un ángel prudente",
  str_homeland_dairy_title_1098 = "Pasa el invierno, llega la primavera",
  str_homeland_dairy_title_1099 = "Sabiduría de Caelestite",
  str_homeland_dairy_content_101 = "Hmm, este es mi primer diario en Cloud Gardens.\nQuiero construir este lugar como mi nuevo hogar, como solía ser Eraveil. Me pregunto si tengo lo que se necesita.\n¡Podré hacerlo con todos apoyándome!",
  str_homeland_dairy_content_102 = "¡Cloud Gardens comienza a sentirse como en casa ahora! ¡Todos están llenos de energía!\nMientras tengamos el impulso, ¡sigamos construyendo el nuevo hogar de todos! ¡Vamos chicos!",
  str_homeland_dairy_content_1001 = "Carleen parece disfrutar pensando sola junto a la Fuente de la Esperanza.\nSolo déjala en paz.",
  str_homeland_dairy_content_1002 = "Hiiro hizo su deseo con cuidado...\nResultó que no estaba rezando a los dioses por nada, pero esperaba en sus deseos poder encontrar una dirección en la vida.",
  str_homeland_dairy_content_1003 = "Charon parece estar recitando un poema cerca de la Plaza Jacinto...? ¿O está cantando?\nbueno Parece que no ha renunciado a sus sueños artísticos y, de hecho, es un... bueno, ¡admirable soñador!",
  str_homeland_dairy_content_1004 = "Eve preparado cuidadosamente muchas cosas para Dawn y Sinsa, pero no por ella misma.\nEve estará satisfecha siempre que pase tiempo con su familia y los haga felices, por lo que no necesita preparar nada extra para ella.",
  str_homeland_dairy_content_1005 = "En base a sus propias necesidades, Smokey presentar una sugerencia sobre el sistema de pedidos de Eraveil. Ella cree que los Aurorianos pueden vivir una vida más cómoda aquí con este sistema.",
  str_homeland_dairy_content_1006 = "Taki pidió modestamente consejos sobre el vuelo de los equipos...\nResultó que quería aprender a volar cometas simplemente porque pensaba que volar cometas era un nuevo negocio lucrativo.\nRealmente merece ser el propietario de Odd Jobs.",
  str_homeland_dairy_content_1007 = "Vice ha estado muy, muy ocupado últimamente,\nParece que administrar los ingresos y los gastos aquí es todo menos fácil...",
  str_homeland_dairy_content_1008 = "Parece que la Sra. Blanc finalmente puede tomar un respiro por un tiempo...",
  str_homeland_dairy_content_1009 = "Los obsesionados con la tecnología Siobhan De repente pensé que la tecnología antigua y la tecnología Caelestite comparten muchas similitudes...\n¿Se puede atribuir esta nueva idea al trabajo de horas extras?",
  str_homeland_dairy_content_1010 = "Amemori quiere saber quién hizo el exquisito diseño aquí... De hecho, quiere replicar esta técnica y usarla en Cloud Island, para que la gente allí pueda vivir una vida mejor.",
  str_homeland_dairy_content_1011 = "Yao explicó en detalle su plan de jubilación y usó su colosal riqueza para disipar las preocupaciones de algunas personas comunes...",
  str_homeland_dairy_content_1012 = "Tourdog todavía no ha renunciado a la idea de encargarme un escrito.\nPero al final, de alguna manera logré darle la vuelta a la mesa y pedirle un trago.\nUh, siento que puedo esperarlo.",
  str_homeland_dairy_content_1013 = "Por alguna razón, cada vez que hablo con Azure, Siempre me resultará difícil responder.\nHoy dijo que mi lugar es como un salón de belleza. ¿Debo tomar eso como un cumplido?",
  str_homeland_dairy_content_1014 = "Este Dia, Lenore finalmente entendió la diferencia entre órdenes y sugerencias.\nEn el futuro, espero que pueda aprender a apreciar la belleza de este mundo...",
  str_homeland_dairy_content_1015 = "Dama Victoria vinculó la circulación del agua con la vida de los aurorianos y se le ocurrió algo profundo...",
  str_homeland_dairy_content_1016 = "Faust me expresó su preocupación de una manera extraña...\n¿Qué le gusta comer a Maleta Blanca? Soy curioso.",
  str_homeland_dairy_content_1017 = "Giles dijo que su apetito creativo se estimula infinitamente aquí, y también cantó una nueva canción infantil.\nSin embargo, ¿qué significa exactamente esta nueva rima...?",
  str_homeland_dairy_content_1018 = "Reinhardt elogió la infraestructura no tan mala aquí, y propuso algunas teorías nuevas...\nDe todos modos, ¿tratamos de entender su punto de vista primero?",
  str_homeland_dairy_content_1019 = "Gronru me invitó a jugar el \"Quiz Game\" con ella...\nEfectivamente, ¡perdí de nuevo!",
  str_homeland_dairy_content_1020 = "Uriel cree que el dolor es eterno, por lo que esos placeres fugaces no tienen sentido...\nPero sin placer, ¿cómo se puede resistir el inmenso poder del dolor?",
  str_homeland_dairy_content_1021 = "Vivian es un buen jefe de personal de hecho...\nElla encuentra los columpios aquí muy interesantes, por lo que le gustaría construir algunos columpios en Illumina.",
  str_homeland_dairy_content_1022 = "Jane está luchando con algo.\nPara el Testigo de Grimy Alley, la objetividad es imprescindible.\nPero cuando sus buenas intenciones rompan la objetividad, ¿qué pensarán los demás?",
  str_homeland_dairy_content_1023 = "resulta que Maggie Lo que más odia no es ser identificada como otra criatura, sino la actitud de los demás hacia ella.",
  str_homeland_dairy_content_1024 = "Hay un motor térmico dentro del Tumbler Puppet, y las operaciones de todos los Jardines de Nubes dependen de Brock constantemente boxeando en él?!\nComo era de esperar, le hicieron una broma de nuevo...",
  str_homeland_dairy_content_1025 = "Tweety parece que le gustan los jardines de nubes.\nPero, ¿cuánto puede esconder en su pequeña cola?",
  str_homeland_dairy_content_1026 = "Pittman siempre vuelve a montar los caballitos balancines cuando no hay nadie alrededor.\nNo entiendo por qué, pero aun así le hice la promesa de ayudarlo a mantener este secreto.",
  str_homeland_dairy_content_1027 = "Barton quería usar los Jardines de las Nubes como una especie de base estratégica...\nCon ese fin, tuvimos algunas conversaciones en profundidad.",
  str_homeland_dairy_content_1028 = "Resultó que Sharona estaba practicando las habilidades secretas del dragón sobre las que leyó en una novela...\nPensé que se sorprendería con esta novela sin sentido, pero me sorprendió su respuesta.",
  str_homeland_dairy_content_1029 = "Eicy compró toda la mercancía en la tienda.\nMe pregunto cuándo podré gastar como ella...",
  str_homeland_dairy_content_1030 = "Connolly está recibiendo algún entrenamiento de desensibilización con Viceel animo...\nPara acostumbrarme a la luz, Connolly Traté de tocar una canción en Hyacinth Square y funcionó sorprendentemente bien.",
  str_homeland_dairy_content_1031 = "Sinsa cree que faltan lugares para pelear y competir en los Jardines de las Nubes, y le preocupa que Eve no podrá soportar el ambiente del apartamento de las chicas...\nAunque suene a problemas, desde otra perspectiva, Sinsa es realmente un buen líder y un buen hermano con gran atención a los detalles.",
  str_homeland_dairy_content_1032 = "Fleur piensa que reparar las mecánicas de Aurorian en diferentes áreas puede traer más diversión nueva... Después de hablar con él, descubrí que su placer es más que eso...",
  str_homeland_dairy_content_1033 = "Yo pregunté Gram para obtener consejos detallados sobre cómo mejorar mis habilidades culinarias.\nMe dijo que no existe tal cosa como el talento en la cocina. La práctica es la única manera de mejorar. A la hora de cocinar hay que evitar las distracciones y cocinar con cariño para mejorar el sabor.",
  str_homeland_dairy_content_1034 = "Su Majestad la Reina admiraba mucho la Torre Jacinto en Eraveil, y tuve la suerte de haber recibido su guía nuevamente.",
  str_homeland_dairy_content_1035 = "Parece que Barton no solo es un maníaco de la guerra, sino también un maníaco de la batalla... Incluso se esfuerza por observar los movimientos de combate de otras personas.\nPero... espera, ¡¿por qué hay gente peleando aquí?!",
  str_homeland_dairy_content_1036 = "Kleken se jactó de que había aprendido una nueva habilidad... Como era de esperar, ¡me hizo una broma otra vez!\nSin embargo, debido a la historia detrás de la Técnica de la Mirada, no puedo enfadarme con él...",
  str_homeland_dairy_content_1037 = "Pierre dijo que se estaban divirtiendo mucho viviendo en la isla, y yo también estaba feliz porque parecían haberse burlado menos y hecho menos bromas...\nPero esa felicidad llegó a un abrupto final cuando descubrí lo que hizo Clucky.",
  str_homeland_dairy_content_1038 = "Seguí la pelusa plateada en el suelo y llegué hasta el pajar. Y Philyshy, que se había dejado la pelusa, roncaba suavemente.\nPara evitar que otros sean alérgicos a la pelusa, tuve que ayudar Philyshy novio...",
  str_homeland_dairy_content_1039 = "Hydrad me dijo que se lastimó el otro día en el Mercado Negro de Umbraton, cuando estaba tratando de pelear por un artículo con alguien.\nCuando descubrí lo que Hydrad quería hacer, me di cuenta de que él también tiene un lado tan diferente de él...",
  str_homeland_dairy_content_1040 = "Genevieve estaba satisfecho con el entorno. El lugar no solo ofrecía su ginebra favorita, sino que las flores eran de su agrado...\nSin embargo, su reacción fue algo interesante cuando supo que todo se debía a que Smokey estaba haciendo las cosas a sus espaldas.",
  str_homeland_dairy_content_1041 = "Regina está trabajando en su nuevo sencillo, y me anima a darle más sugerencias...\nPero de sus palabras, obtuve más información: en comparación con Barbara, Regina parece pensar menos en sus contrapartes que pretenden ser otra cosa.",
  str_homeland_dairy_content_1042 = "no esperaba Pact gustarle tanto columpiarse.\n¿Construiremos algunos más en el futuro?",
  str_homeland_dairy_content_1043 = "Hoy, finalmente convencí Areia para dar un paseo al aire libre.\nEspero que su sonrisa se quede con ella para siempre.",
  str_homeland_dairy_content_1044 = "Kafka me dijo que Franz está muy contento aquí. Hay mucho espacio, y también ha conocido a muchos nuevos compañeros de juego... ¡y ni siquiera babea tanto!\nBueno, espera... ¿a dónde se fue la baba reducida?",
  str_homeland_dairy_content_1045 = "Nails Creyó erróneamente que todos se confesaban frente a la Fuente de la Esperanza, por lo que también comenzó a confesarse sin parar...\nEspero que realmente pueda encontrar consuelo en esto.",
  str_homeland_dairy_content_1046 = "Uriah parece gustarle mucho la vista de Eraveil.\nAproveché la oportunidad para decirle mi anhelado deseo y, afortunadamente, estuvo feliz de ayudarme con eso.",
  str_homeland_dairy_content_1047 = "Vive el día... TessaEl estilo de vida de es un poco envidiable.\nPero no todos pueden ser tan libres y fáciles.",
  str_homeland_dairy_content_1048 = "Hachi quiere convertir los Jardines de las Nubes en una sala de exposiciones natural.\nSupuestamente, eso puede atraer a muchos turistas y traer muchos beneficios.\n¿Debo confiar en él? ¡Se siente como una trampa!",
  str_homeland_dairy_content_1049 = "Vice parece un poco deprimido, tal vez por ese incidente.\nPor suerte mis chistes malos la hicieron reír.\nVice me ayudó mucho, debo acompañarla para recuperar su pasado.",
  str_homeland_dairy_content_1058 = "Nina ha podido montar a caballo desde que era una niña, por lo que nunca ha montado un caballo balancín.\nCuando escucha que algunas personas no pueden permitirse comprar un caballito balancín, decide hacer algunos para dárselos a los que quieren uno.\nBueno... Nina es una persona de buen corazón.",
  str_homeland_dairy_content_1059 = "Sanae decide llamar al jardín Flowerbed of Love.\nElla también promete cuidarlo.\nSin embargo, todo lo que quiero es que deje de tropezar todo el tiempo... ¡Duele solo mirarla!",
  str_homeland_dairy_content_1060 = "Dawn está pensando en silencio en el escritorio...\nMe sorprende cuando me dice que puede identificar a las personas con solo escuchar sus pasos.\nUrgh, pero hay una excepción para todo... Al menos la razón que da para identificar a Sinsa es frustrante.",
  str_homeland_dairy_content_1061 = "Barbara parece estar practicando su nuevo sencillo en el Zaki Music Stage, pero parece tener algunas preocupaciones...\nDespués de charlar con ella, aunque me choca la actitud de Bárbara hacia la música fresca, su actitud hacia otras cosas está dentro de mis expectativas...",
  str_homeland_dairy_content_1062 = "Leona está practicando boxeo enfáticamente, como si estuviera llena de resentimiento...\nResulta que así es como ella se desahoga.\nSin embargo, creo que dije algo que no debí haber dicho...",
  str_homeland_dairy_content_1063 = "Naroxel está hablando con los pájaros en su escritorio...\nEstá preocupada por mi estado de ánimo reciente, así que me enseñó una nueva técnica de respiración.",
  str_homeland_dairy_content_1064 = "Migard realmente está a la altura de su reputación como oficial que se especializa en biotecnología. ¡Una mirada es todo lo que necesita para saber qué árboles han sido modificados genéticamente!",
  str_homeland_dairy_content_1065 = "Como se esperaba de Nina... ¡nunca deja pasar un poco de inspiración!\nProbablemente debería aprender de su tenacidad cuando se trata de perseguir sus sueños.",
  str_homeland_dairy_content_1066 = "Hoy me encontré con Sahn, el líder del clan Pangalo. Es muy reservado. Aunque hubo algunos altibajos en nuestras interacciones, al final todos estaban felices.",
  str_homeland_dairy_content_1067 = "¡Me tomó por sorpresa que los Pangalos realmente disfrutaran del death metal de Regina! ¡Fueron tan lejos como para formar un grupo de apoyo para ella! Es todo muy extraño, pero al menos salió bien.",
  str_homeland_dairy_content_1068 = "Carleen menatap telapak tangannya. Tiba-tiba, dia mengepalkan telapak tangannya seolah-olah dia telah mengambil keputusan atau mengambil keputusan... Ternyata dia sekarang mengerti \"makna doa\".",
  str_homeland_dairy_content_1069 = "Beryl ha estado junto al río todo este tiempo? Podría ser...\nMe di cuenta de que estaba equivocado e incluso dejé Beryl jugar un rato.\nSin embargo, nada de esto importa. es lo mejor siempre y cuando Beryl puede sentirse relajado aquí.",
  str_homeland_dairy_content_1070 = "Ciel ha estado preocupado por un error de cálculo en un plano recientemente. Incluso consideró trabajar para mí para ganar algo de dinero y comprar una costosa calculadora mecánica.\nAl final, se dio cuenta de que su comprensión estaba equivocada, no el plan.\nParece que la inspiración a veces es parte de un plan.",
  str_homeland_dairy_content_1071 = "Fia lleva su felicidad en la manga.\nBajo su influencia, también pasé mucho tiempo jugando en el tobogán.",
  str_homeland_dairy_content_1072 = "Dormí en la tumbona toda la tarde.\nRecuerdo vagamente que fue Jeno quien me puso a dormir... No puedo seguir soñando ahora, ¿verdad?",
  str_homeland_dairy_content_1073 = "Hay muchas maneras de proteger las cosas que amas.\nEsto es lo que aprendí de Rainbow hoy.",
  str_homeland_dairy_content_1076 = "Incluso en Cloud Gardens, Pollux aún conserva sus rutinas y hábitos de Euphoria.",
  str_homeland_dairy_content_1077 = "Paloma siempre usa un lenguaje mordaz y mordaz para encubrir cuánto extraña a su familia. Espero que pueda visitar Cloud Gardens a menudo en el futuro y encontrar la paz interior.",
  str_homeland_dairy_content_1078 = "Es posible que Casta no haya llegado al casino, pero pescó muchos peces junto al río...\nSu captura la deleitó mucho más que apostar.\nSupongo que ese es el encanto de la pesca!",
  str_homeland_dairy_content_1079 = "A Hedy también le encantan los helados, ¡así que finalmente encontramos puntos en común!\nPero, ¿realmente existe el helado con sabor a \"libro antiguo\"?",
  str_homeland_dairy_content_1080 = "Judge Jr. ama las estatuas de estilo Caelestite.\nHice uno para él con arcilla, pero no parecía muy satisfecho y se limitó a deambular por la Doncella Viajera.",
  str_homeland_dairy_content_1081 = "¡Como era de esperar de Lilica! De hecho, descubrió lo que se supone que debes hacer con la muñeca Windelion.\nLilica también me prometió que haría una película sobre Eraveil, pero espero que escriba bien el guión...",
  str_homeland_dairy_content_1082 = "¡Gracias a Minos, descubrí cómo funciona la escultura de vela de Windelion!",
  str_homeland_dairy_content_1083 = "¿Quién hubiera imaginado que Sadie tenía tanto talento musical? Todos los que escuchan la melodía del tambor no pueden evitar balancearse con él.\n¡La próxima vez cantaré hip hop para todos!",
  str_homeland_dairy_content_1084 = "Si Michenny cuida de los animalitos y los ve crecer, tal vez pueda entender...\nque la importancia de la vida es algo que no se puede medir en términos de valor.",
  str_homeland_dairy_content_1085 = "Hoy, decidí construir un estudio de cine en Cloud Gardens para todos.",
  str_homeland_dairy_content_1086 = "Beretta es muy disciplinada e insiste en correr todos los días. Recién hoy descubrí que está tratando de mejorar su condición física y convertirse en una mejor doctora. Ella realmente es digna de mi admiración.",
  str_homeland_dairy_content_1087 = "Axelia ha aparecido mucho cerca de ese Windelion Drum recientemente...\nDespués de hablar con ella, ahora entiendo por qué le gusta la música electrónica.",
  str_homeland_dairy_content_1088 = "Nadine se ha ofrecido como voluntaria para ser la Guardia Nocturna de Cloud Gardens. ¡No puedo simplemente ignorar su contribución a pesar de que se ofreció como voluntaria para este deber!\nDebo pensar en una recompensa para Nadine...",
  str_homeland_dairy_content_1089 = "Para convertirme en el mejor pescador indiscutible y obtener financiación para el museo, me inscribí en el concurso de pesca An Extraordinary Catch.",
  str_homeland_dairy_content_1090 = "Por fin, con ánimo, vencí a todos los Maestros Pescadores y al campeón defensor. Si bien no obtuve la financiación que necesitaba, demostré que soy el mejor pescador de Eraveil.",
  str_homeland_dairy_content_1091 = "Es inusual ver a Vic aventurarse fuera de su habitación y, como era de esperar, está planeando aún más de sus travesuras... ¿¡Está tratando de transformar este lugar y el Coloso en su propio centro de investigación privado!?",
  str_homeland_dairy_content_1092 = "El nuevo álbum necesita una nueva dinámica y un nuevo tema, pero ¿qué tipo de estilo es mejor? Goldie no está segura de lo que debe hacer, pero no importa qué estilo elija, ¡sin duda lo logrará a la perfección!",
  str_homeland_dairy_content_1093 = "Brandy ha estado ocupado tomando fotos por todos lados otra vez. Esta vez, tomó una foto perfecta sin siquiera quererlo, capturando la luz de la manera más conmovedora. Supongo que por eso dicen que la fotografía es el arte de las luces y las sombras...",
  str_homeland_dairy_content_1094 = "Los gatos se apoderaron del estante. Parece que les encanta...",
  str_homeland_dairy_content_1095 = "Liqing está buscando al perezoso Tinytail, pero también parece estar...",
  str_homeland_dairy_content_1096 = "Yuebai dice que si quieres convertirte en un maestro nadador, debes sentir el aliento del agua, y si quieres sentir el aliento del agua, debes pararte a la orilla del agua durante 10 000 horas. ¿Se supone que eso es real?",
  str_homeland_dairy_content_1097 = "Michael parece estar preocupado de que el candelero provoque un incendio accidentalmente, pero tal vez solo esté buscando una excusa para comprarlo.",
  str_homeland_dairy_content_1098 = "Cloud Gardens está muy lejos de las ruinas desoladas que solía ser Eraveil. El paisaje causa una profunda impresión en Jeriah.",
  str_homeland_dairy_content_1099 = "Kya se monta en una taza de café giratoria por primera vez, lo que le parece un poco intenso. Después de un mareo, pone en orden los aspectos más importantes de su nuevo trabajo...",
  str_homeland_dairy_reply_101 = "¡Claro que podemos, Navegante!",
