  str_homeland_dairy_condition_1098 = "Jeriah desea vivir en un ambiente más cómodo. Ella espera mucho más <color=#FEF49B>Habitabilidad</color> para este lugar",
  str_homeland_dairy_condition_1099 = "Kya quiere montar un <color=#FEF49B>taza de café giratoria</color> para experimentar lo que se siente al estar mareado.",
  str_homeland_dairy_title_1074 = "¡Empieza a cavar!",
  str_homeland_dairy_title_1075 = "Verano perezoso",
  str_homeland_dairy_content_1074 = "Hoy, he decidido construir un parque acuático para que todos los Aurorianos se refresquen y se diviertan en los Jardines de las Nubes.",
  str_homeland_dairy_content_1075 = "Ayudé a Vice a reparar la máquina de helados y ayudé a Fia a aprender a nadar. Finalmente, con la ayuda de Carleen y Vice, también pude disfrutar de la belleza del parque acuático.",
  str_homeland_dairy_reply_1074 = "¡La piscina está en construcción!",
  str_homeland_dairy_reply_1075 = "¡Nada al contenido de tu corazón!",
  str_homeland_dairy_condition_1074 = "Estos años <color=#FEF49B>el verano</color> parece muy caliente también!",
  str_homeland_dairy_condition_1075 = "<color=#FEF49B>fia y vicio</color> Parece que necesitan tu ayuda.",
  str_homeland_dairy_title_1100 = "Aliento de la naturaleza",
  str_homeland_dairy_title_1101 = "Investigación de postres",
  str_homeland_dairy_title_1102 = "Mar en el sueño",
  str_homeland_dairy_title_1103 = "Preferencias de los nobles",
  str_homeland_dairy_content_1100 = "Poder Gabriel realmente sentir la respiración de los árboles? La capacidad de comunicarse con las plantas es realmente especial.",
  str_homeland_dairy_content_1101 = "Leyn está muy interesado en el chocolate que compré. ¡Esta caja de chocolates está hábilmente hecha y tiene un sabor muy tentador también!",
  str_homeland_dairy_content_1102 = "Tina parece anhelar la playa, pero es impactante lo rápido que puede quedarse dormida...",
  str_homeland_dairy_content_1103 = "Matthieu quiere renovar el Rose Pavilion. ¿Está haciendo esto para atraer la atención de las chicas? ¿Es posible que realmente quiera estudiarlo?",
  str_homeland_dairy_reply_1100 = "La brisa ligera... es tan refrescante.",
  str_homeland_dairy_reply_1101 = "Chocolate...",
  str_homeland_dairy_reply_1102 = "La playa... debe ser tan hermosa.",
  str_homeland_dairy_reply_1103 = "A este pabellón parece que le falta algo...",
  str_homeland_dairy_condition_1100 = "Gabriel no ha dicho nada, pero espera que la <color=#FEF49B>habitabilidad</color> se puede mejorar mucho aquí.",
  str_homeland_dairy_condition_1101 = "Hace Leyn como esto <color=#FEF49B>Chocolates de corona de luna</color>?",
  str_homeland_dairy_condition_1102 = "Tina parece estar interesado en esto <color=#FEF49B>Sillón de playa</color>.",
  str_homeland_dairy_condition_1103 = "Matthieu dijo que quiere un <color=#FEF49B>lugar para leer y disfrutar del paisaje</color>.",
  str_homeland_dairy_title_1104 = "libro de respuestas",
  str_homeland_dairy_title_1105 = "detectives y musica",
  str_homeland_dairy_title_1106 = "Pequeño fracaso",
  str_homeland_dairy_title_1107 = "experiencia del pastor",
  str_homeland_dairy_title_1108 = "Inspiración Musical",
  str_homeland_dairy_content_1104 = "Hati ha descubierto que el Libro de las Respuestas responderá cualquier pregunta que se le haga con una precisión aterradora...",
  str_homeland_dairy_content_1105 = "La música parece no tener nada en común con un detective, ¡pero una colisión entre los dos puede crear chispas inesperadas y maravillosas! Goldie se inspiró para su concierto a partir de esto, ¡así que no puedo esperar a que se celebre el próximo concierto!",
  str_homeland_dairy_content_1106 = "Un técnico experto como Fleur puede identificar fácilmente problemas mecánicos, ¡pero los problemas relacionados con el discurso lo dejarán boquiabierto!",
  str_homeland_dairy_content_1107 = "Istvan está mirando fijamente la pizarra, pero en lugar de estar obsesionado con investigar y resolver misterios, parece tener algo diferente en mente...",
  str_homeland_dairy_content_1108 = "Kristen está tarareando una melodía junto al tocadiscos. Creo que de repente tuvo una nueva inspiración para una canción...",
  str_homeland_dairy_reply_1104 = "Es bastante apropiado.",
  str_homeland_dairy_reply_1105 = "♪ ¡La-la-laaaa! ♪",
  str_homeland_dairy_reply_1106 = "Déjame ver...",
  str_homeland_dairy_reply_1107 = "Interesante.",
  str_homeland_dairy_reply_1108 = "¡Ay, qué hermosa música!",
  str_homeland_dairy_condition_1104 = "Hati parece querer un juego de <color=#FEF49B>Sujetalibros de detective</color>.",
  str_homeland_dairy_condition_1105 = "Goldie está mostrando cierto interés en el <color=#FEF49B>Violín del detective</color>.",
  str_homeland_dairy_condition_1106 = "Fleur está muy interesada en el <color=#FEF49B>Carrito de Café del Detective</color>.",
  str_homeland_dairy_condition_1107 = "¿Istvan estará interesado en el <color=#FEF49B>Tablero del caso del detective</color>?",
  str_homeland_dairy_condition_1108 = "Kristen solo le dice lo que realmente piensa <color=#FEF49B>amigos</color>.",
  str_homeland_dairy_title_1114 = "El arte del cartógrafo",
  str_homeland_dairy_title_1115 = "Latte casero",
  str_homeland_dairy_title_1116 = "El resplandor de la linterna",
  str_homeland_dairy_title_1117 = "Potenciadores del cerebro",
  str_homeland_dairy_content_1114 = "Leo recibe un mapa de la frontera de sus subordinados, pero está anotado con un texto pequeño y confuso. Entonces, ¿qué está escrito realmente en él?",
  str_homeland_dairy_content_1115 = "El café con leche de Yingel es delicioso, pero sigo sintiendo que la verdadera razón por la que aprendió a hacer café debe tener algo que ver con lo mucho que ama la leche...",
  str_homeland_dairy_content_1116 = "Anatoli parece fascinado por la linterna en Cloud Gardens. Parece que arde día y noche, pero ¿quién le echa aceite...?",
  str_homeland_dairy_content_1117 = "¿Son realmente tan asombrosos los Brain Boosters de Raphael?",
  str_homeland_dairy_reply_1114 = "¿Qué está escrito en esto?",
  str_homeland_dairy_reply_1115 = "¡El café con leche es de hecho más fragante y suave!",
  str_homeland_dairy_reply_1116 = "Esta linterna...",
  str_homeland_dairy_reply_1117 = "Esta es una píldora de sabor tan extraño...",
  str_homeland_dairy_condition_1114 = "Leo parece querer un <color=#FEF49B>Lupa de detective</color>.",
  str_homeland_dairy_condition_1115 = "Yingel está mostrando cierto interés en el <color=#FEF49B>Juego de café del detective</color>.",
  str_homeland_dairy_condition_1116 = "Anatoli está muy interesado en el <color=#FEF49B>Linterna de mano del detective</color>.",
  str_homeland_dairy_condition_1117 = "Raphael espera mucho más <color=#FEF49B>habitabilidad</color> para este lugar",
  str_homeland_dairy_title_1118 = "Falta de elegancia",
  str_homeland_dairy_title_1119 = "Adivinación",
  str_homeland_dairy_title_1120 = "la cola negra",
  str_homeland_dairy_title_1121 = "Memoria eterna",
  str_homeland_dairy_content_1118 = "Schwartz está en algún lugar cerca de la Regal Remembrance Throne y no está satisfecho con las instalaciones de Cloud Gardens. Él puede tener un punto, ¿tal vez podamos encontrar una manera de agregar una fragancia agradable a Cloud Gardens en el futuro?",
  str_homeland_dairy_content_1119 = "Jakine me está adivinando el futuro. Ella parece haber descubierto la verdad de la adivinación, e incluso yo entiendo el significado de la adivinación un poco mejor ahora...",
  str_homeland_dairy_content_1120 = "Cuscuta ama las colas negras. ¿Estaría dispuesta a criar algunas flores hermosas conmigo?",
  str_homeland_dairy_content_1121 = "Mia perdió la memoria hace un tiempo, así que cuando vio esa bola de cristal, no pudo evitar preguntarse... Si pudieras elegir un día para recordar por el resto de tu vida, ¿cuál elegirías?",
  str_homeland_dairy_reply_1118 = "¿Un ambiente insuficientemente elegante...? ¡Eso sí que es una grave falta de etiqueta!",
  str_homeland_dairy_reply_1119 = "¡Ajá, todo se está volviendo claro para mí ahora!",
  str_homeland_dairy_reply_1120 = "Si caigo en un sueño profundo, ¿Black Tails florecerá en todo mi cuerpo...?",
  str_homeland_dairy_reply_1121 = "En lugar de preocuparse por olvidar el pasado, es más importante apreciar el presente.",
  str_homeland_dairy_condition_1118 = "Schwartz: Almighty Clamor está muy interesado en el <color=#FEF49B>Regal Trono del Recuerdo</color>.",
  str_homeland_dairy_condition_1119 = "Jakine parece estar buscando <color=#FEF49B>algo para adivinar</color>.",
  str_homeland_dairy_condition_1120 = "Cuscuta espera mucho más <color=#FEF49B>Habitabilidad</color> para este lugar",
  str_homeland_dairy_condition_1121 = "Mia: Lustrous Soul parece estar muy interesado en el <color=#FEF49B>Regal Bola de cristal del recuerdo</color>.",
  str_homeland_dairy_title_1122 = "¡Crece grande y fuerte!",
  str_homeland_dairy_title_1123 = "Reglas de meditación",
  str_homeland_dairy_title_1124 = "Solo derríbalo",
  str_homeland_dairy_content_1122 = "Después de ver las plantas verdes, Joshua me cuenta sus experiencias con el cultivo de flores, pero no se olvida de bromear conmigo. ¿Eh? ¿Por qué mi cara está sonrojada...",
  str_homeland_dairy_content_1123 = "Ms. Blanc está meditando. Escuché que la meditación es una forma de mejorar, pero Ms. Blanc cree que mis pensamientos no son prácticos...",
  str_homeland_dairy_content_1124 = "Odi se está aburriendo de nuevo y esta vez quiere romper una farola. Debo encontrar una manera de detener esto...",
  str_homeland_dairy_reply_1122 = "Será tan bonito aquí si hay flores frescas creciendo por todas partes.",
  str_homeland_dairy_reply_1123 = "Concéntrate... Oh, estoy soñando despierta otra vez.",
  str_homeland_dairy_reply_1124 = "¡Ja ja! ¡Romper en pedazos! ¡Destruye todo!",
  str_homeland_dairy_condition_1122 = "Joshua está muy interesado en el <color=#FEF49B>Planta de la nostalgia</color>.",
  str_homeland_dairy_condition_1123 = "Blanc: Pura Cordis parece estar buscando un lugar que sea <color=#FEF49B>fresco y lleno de vegetación</color>.",
  str_homeland_dairy_condition_1124 = "Odi quiere un <color=#FEF49B>pieza mecánica que emite luz</color>.",
  str_homeland_dairy_title_1125 = "¡El mar azul salobre!",
  str_homeland_dairy_title_1126 = "¿Un nuevo proyecto?",
  str_homeland_dairy_title_1127 = "para la posteridad",
  str_homeland_dairy_content_1125 = "Lorelei está trabajando en un nuevo proyecto prospectivo: ¡turismo isleño! Es por eso que ella comenzó a interesarse tanto en mis instalaciones e incluso trató de absorberme en sus planes...",
  str_homeland_dairy_content_1126 = "Cuando surgió el tema de esas tazas de té giratorias de Mooncrown, Cena de repente comenzó a contar otra historia extraña...",
  str_homeland_dairy_content_1127 = "¡Mientras miraba el monumento, Bopper se inspiró para comenzar a pensar más seriamente en el futuro de Rediesel Wrench! Charlamos un rato y luego se le ocurrió una nueva idea...",
  str_homeland_dairy_reply_1125 = "¡Vamos a ponernos en marcha hacia el mar azul salobre!",
  str_homeland_dairy_reply_1126 = "No estoy bromeando... ¡Estoy tratando de pensar aquí!",
  str_homeland_dairy_reply_1127 = "¡Este tipo de monumento es exactamente lo que necesita Rediesel Wrench!",
  str_homeland_dairy_condition_1125 = "Lorelei está muy interesada en la <color=#FEF49B>Atalaya de salvavidas</color>.",
  str_homeland_dairy_condition_1126 = "Cena necesita unas <color=#FEF49B>copas giratorias</color>.",
  str_homeland_dairy_condition_1127 = "Bopper está muy interesado en el <color=#FEF49B>Monumento de las Líneas</color>.",
  str_homeland_dairy_title_1128 = "Reclutamiento en cartelera",
  str_homeland_dairy_title_1129 = "Antes del estandarte",
  str_homeland_dairy_content_1128 = "El Gran Mariscal Wrath tiene algunas opiniones sobre el anuncio de reclutamiento. Nuestra charla parece inspirarla, pero también le causa algunos problemas...",
  str_homeland_dairy_content_1129 = "Joselyne permanece largo rato ante el cartel. ¿Está ella orando? Aunque luego dice que no le importa, espero que mi saludo no la distraiga...",
  str_homeland_dairy_reply_1128 = "¡La Federación Illumina da la bienvenida a todos los soldados ambiciosos!",
  str_homeland_dairy_reply_1129 = "Que todos tengamos nuestra guía.",
  str_homeland_dairy_condition_1128 = "El comandante Wrath está interesado en el <color=#FEF49B>cartel publicitario de reclutamiento</color>.",
  str_homeland_dairy_condition_1129 = "Joselyne está interesada en el <color=#FEF49B>Banner de Lumopolis</color>.",
  str_homeland_dairy_title_1130 = "Huesos en los Jardines de las Nubes",
  str_homeland_dairy_title_1131 = "\"Carro mecánico\"",
  str_homeland_dairy_title_1132 = "Picnic juntos",
  str_homeland_dairy_content_1130 = "Al ver el Corredor Dentado dentro de Cloud Gardens, Antony lo considera un material de investigación raro.",
  str_homeland_dairy_content_1131 = "Zarya se queda perpleja al ver el modelo del carruaje, así que le doy un rápido resumen.",
  str_homeland_dairy_content_1132 = "La número 33 está pensando en invitar a amigos a un picnic y necesito ayudarla a pensar en ideas.",
  str_homeland_dairy_reply_1130 = "\"Parece que mis conocimientos están a punto de recibir un impulso nuevamente\".",
  str_homeland_dairy_reply_1131 = "\"¿Es realmente tan difícil operar esta cosa? Lo probaré cuando haya una posibilidad\".",
  str_homeland_dairy_reply_1132 = "\"Preparativos para el picnic en progreso\".",
  str_homeland_dairy_condition_1130 = "Antony sangat tertarik dengan <color=#FEF49B>Koridor Bergerigi</color>.",
  str_homeland_dairy_condition_1131 = "Zarya está muy interesado en el <color=#FEF49B>Auto del Detective</color>.",
  str_homeland_dairy_condition_1132 = "Nomor 33 sangat tertarik dengan <color=#FEF49B>Taplak Meja Piknik</color>.",
  str_homeland_dairy_title_1133 = "Silla colgante de recuerdos",
  str_homeland_dairy_title_1134 = "Transporte Flotante",
  str_homeland_dairy_content_1133 = "Después de ver la silla colgante de piedra esmaltada dentro de Cloud Gardens, parece que Rebecca recuerda un recuerdo de la infancia.",
  str_homeland_dairy_content_1134 = "Después de ver el vehículo adornado dentro de los Jardines de las Nubes, Isa parece recordar un recuerdo querido.",
  str_homeland_dairy_reply_1133 = "\"Esto realmente me lleva al pasado...\"",
  str_homeland_dairy_reply_1134 = "\"¿No crees que este coche... es súper genial?!\"",
  str_homeland_dairy_condition_1133 = "Rebecca está muy interesado en la <color=#FEF49B>silla colgante de piedra esmaltada</color>.",
  str_homeland_dairy_condition_1134 = "Isa está muy interesado en el <color=#FEF49B>Vehículo festoneado</color>.",
  str_homeland_dairy_title_1135 = "Máquinas y los Tiempos",
  str_homeland_dairy_title_1136 = "Renuente a Despertar",
  str_homeland_dairy_title_1137 = "Cometa sentimental",
  str_homeland_dairy_content_1135 = "Xuan Ji se siente nostálgico acerca del Marco Giratorio, pero ya no es útil. Realmente los tiempos han cambiado.",
  str_homeland_dairy_content_1136 = "Cuando Li Tianxian quiere dormir, puede quedarse dormido incluso si está apoyado en un reloj. ¿Debería envidiarlo...?",
  str_homeland_dairy_content_1137 = "Dantang dijo que volar cometas es una de las actividades favoritas de los niños de Longzhou, y está feliz de ir a volar cometas conmigo.",
  str_homeland_dairy_reply_1135 = "\"¡Apuesto a que ha estado funcionando normalmente durante mucho tiempo!\"",
  str_homeland_dairy_reply_1136 = "\"¡Qué vergonzoso! Esto significa que incluso este reloj de sol es más libre que yo.\"",
  str_homeland_dairy_reply_1137 = "\"El tiempo siempre vuela cuando no hay nada de qué preocuparse...\"",
  str_homeland_dairy_condition_1135 = "Xuan Ji está muy interesado en el <color=#FEF49B>Marco giratorio</color>.",
  str_homeland_dairy_condition_1136 = "Li Tianxian está muy interesado en el <color=#FEF49B>Reloj de sol</color>.",
  str_homeland_dairy_condition_1137 = "Dantang está muy interesado en el <color=#FEF49B>estante para cometas</color>.",
  str_homeland_dairy_title_1138 = "Guardia Costoso",
  str_homeland_dairy_title_1139 = "Reloj de sol",
  str_homeland_dairy_title_1140 = "¿Turismo?!",
  str_homeland_dairy_content_1138 = "Parece que muchas partes interesantes se han utilizado en el Espantapájaros picado de viruela que Vergil encontró en Cloud Gardens.",
  str_homeland_dairy_content_1139 = "El Señor Sombrío está fascinado por el Reloj de Sol. Le apasiona coleccionar relojes. Incluso me contó sobre los diversos relojes que ha coleccionado.",
  str_homeland_dairy_content_1140 = "Parece que la mente de negocios de Lady Sheol está activa todo el tiempo. Quizás por eso ha hecho del Gremio de Explorador Nublar un éxito masivo.",
  str_homeland_dairy_reply_1138 = "\"Que interesante.\"",
  str_homeland_dairy_reply_1139 = "\"Es tan revelador ver un estilo diferente de reloj.\"",
  str_homeland_dairy_reply_1140 = "\"Estoy esperando con ansias el futuro de Cloud Gardens, y también el tuyo.\"",
  str_homeland_dairy_condition_1138 = "A Virgilio le interesa mucho el <color=#FEF49B>Espantapájaros picado de viruela</color>.",
  str_homeland_dairy_condition_1139 = "Istvan está muy interesado en el <color=#FEF49B>Reloj de sol</color>.",
  str_homeland_dairy_condition_1140 = "Sheol está muy interesado en el <color=#FEF49B>Dormitorio Gardens</color>.",
  str_homeland_dairy_title_1141 = "Comprensión Profunda",
  str_homeland_dairy_content_1141 = "Después de investigar el contenedor de reciclaje automático, Algol aprecia la tecnología de Caelestite, de una manera algo incómoda, sin embargo.",
  str_homeland_dairy_reply_1141 = "\"Interesante.\"",
  str_homeland_dairy_condition_1141 = "Algol está muy interesado en la <color=#FEF49B>Papelera de reciclaje automática</color>.",
  str_homeland_dairy_title_1142 = "Susurro junto a la estatua",
  str_homeland_dairy_title_1143 = "Arte del artilugio",
  str_homeland_dairy_content_1142 = "Hablé con Chen'ni sobre la estatua, y ella dijo, \"¿Habrá alguna vez una estatua de mí...?\"",
  str_homeland_dairy_content_1143 = "A Luo Song realmente le gusta este artículo con forma de Eclipsite, elogia su comodidad y durabilidad. También comparte mucho sobre el equipo marcial.",
  str_homeland_dairy_reply_1142 = "\"¡Me encantaría una estatua al estilo de Astra!\"",
  str_homeland_dairy_reply_1143 = "\"¡Un buen equipo también te enseña mucho!\"",
  str_homeland_dairy_condition_1142 = "Chen'ni está muy interesada en la <color=#FEF49B>Estatua de la Doncella Viajera</color>.",
  str_homeland_dairy_condition_1143 = "Luo Song está muy interesado en el <color=#FEF49B>Marioneta de vaso</color>.",
  str_homeland_dairy_title_1144 = "Refugio del Faro",
  str_homeland_dairy_content_1144 = "Tiare mira la Linterna de la Corte de Vista, recordando el faro que una vez protegió a Northland.",
  str_homeland_dairy_reply_1144 = "Resulta que, no es el faro lo que es importante, sino la luz...",
  str_homeland_dairy_condition_1144 = "Tiare encuentra la <color=#FEF49B>Linterna de la Corte Overlook</color> bastante intrigante.",
  str_homeland_dairy_title_1145 = "El Maestro Ingeniero",
  str_homeland_dairy_content_1145 = "Rachel quiere hacer un caballito balancín para su hermana. Siempre está tan preocupada por los demás; ¿cuándo empezará a pensar en sus propias necesidades?",
  str_homeland_dairy_reply_1145 = "Realmente espero que a mi hermana le guste mi regalo.",
  str_homeland_dairy_condition_1145 = "Me pregunto si a Rachel le gustaría un <color=#FEF49B>Caballo balancín de lujo</color>?",
  str_homeland_dairy_title_1146 = "Tesoro de Vacaciones",
  str_homeland_dairy_content_1146 = "¡Será mejor que esté atento! Estoy perdido si me encuentro con la Muñeca Windelion de Zeta...",
  str_homeland_dairy_reply_1146 = "¡Me estremezco solo de pensar en alguien rompiéndolo!",
  str_homeland_dairy_condition_1146 = "A Zeta le debería gustar una <color=#FEF49B>Muñeca Windelion</color>, ¿verdad?"
}
return config
